"""CPU-only, read-only launcher for the bounded T4 stratified data view.

Does not authenticate, call Drive at import time, load a model, or start training.
Call launch_t4_sampler() explicitly from the owner-approved notebook cell.
"""
import base64, hashlib, importlib.util, json, pathlib, sys, threading, time, traceback

WORKER_B64 = ''
EVAL_FIXTURES_B64 = ''
WORKER_SHA256 = "da97a28f5903bc1a0f08cb5554531420c74e2340b6013e79f0000d96096663f1"
EVAL_FIXTURES_SHA256 = "81ddf4261063b5832b6f55168ca160bf5cec26a5cabd83b7fedaa00ddecec100"
EXPECTED_EVAL_FIXTURES = 28
BUDGET_ROOT = pathlib.Path('/content/mathvisionkid_t4_budget_3h_20261023')
SAMPLING_ROOT = BUDGET_ROOT / 'sampling'
INVENTORY_PATH = SAMPLING_ROOT / 'sampling_metadata_inventory.json'


def _unwrap_inventory(value):
    required = {'release', 'chat_member_metadata', 'artifact_metadata'}
    if isinstance(value, dict) and required <= set(value):
        return value
    if isinstance(value, dict):
        for key in ('inventory', 'metadata', 'receipt', 'result', 'structured_content'):
            if key in value:
                try:
                    result = _unwrap_inventory(value[key])
                    if result:
                        return result
                except (TypeError, ValueError, KeyError, json.JSONDecodeError):
                    pass
        for output in value.get('outputs', []):
            for content in output.get('text', []):
                if isinstance(content, str):
                    try:
                        parsed = json.loads(content)
                        if required <= set(parsed):
                            return parsed
                    except (json.JSONDecodeError, TypeError):
                        continue
    raise ValueError('sampling_metadata_inventory.json lacks pinned release/member/artifact metadata')


def _save_status(status):
    SAMPLING_ROOT.mkdir(parents=True, exist_ok=True)
    temp = SAMPLING_ROOT / 'launcher_status.pending'
    temp.write_text(json.dumps(status, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    temp.replace(SAMPLING_ROOT / 'launcher_status.json')


def launch_t4_sampler():
    global sampling_worker_thread, sampling_worker_status
    if 'independentDriveAPI' not in globals():
        raise RuntimeError('Owner must provide the existing read-only independentDriveAPI object')
    if 'sampling_worker_thread' in globals() and sampling_worker_thread.is_alive():
        raise RuntimeError('Sampler worker already running')
    worker_bytes = base64.b64decode(WORKER_B64)
    eval_bytes = base64.b64decode(EVAL_FIXTURES_B64)
    if hashlib.sha256(worker_bytes).hexdigest() != WORKER_SHA256:
        raise ValueError('embedded sampler worker SHA256 mismatch')
    if hashlib.sha256(eval_bytes).hexdigest() != EVAL_FIXTURES_SHA256:
        raise ValueError('embedded eval fixture SHA256 mismatch')
    SAMPLING_ROOT.mkdir(parents=True, exist_ok=True)
    worker_path = SAMPLING_ROOT / 'colab_train_view_worker.py'
    worker_path.write_bytes(worker_bytes)
    eval_path = SAMPLING_ROOT / 'new_eval_candidates.jsonl'
    eval_path.write_bytes(eval_bytes)
    if not INVENTORY_PATH.is_file():
        raise FileNotFoundError(f'Expected existing metadata inventory: {INVENTORY_PATH}')
    inventory = _unwrap_inventory(json.loads(INVENTORY_PATH.read_text(encoding='utf-8')))
    eval_rows = [json.loads(line) for line in eval_bytes.decode('utf-8').splitlines() if line.strip()]
    if len(eval_rows) != EXPECTED_EVAL_FIXTURES:
        raise ValueError(f'Expected {EXPECTED_EVAL_FIXTURES} eval fixtures, found {len(eval_rows)}')
    spec = importlib.util.spec_from_file_location('mvk_colab_train_view_worker', worker_path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    eval_hash_path = SAMPLING_ROOT / 'protected_eval_question_hashes.jsonl'
    with eval_hash_path.open('w', encoding='utf-8') as output:
        for row in eval_rows:
            problem = row.get('userproblem')
            if not isinstance(problem, str) or not problem.strip():
                raise ValueError('Eval fixture is missing userproblem text')
            item = {'id': row.get('id'), 'grade': row.get('grade'), 'skill': row.get('skill'),
                    'mode': row.get('mode'), 'question_sha256': module.question_sha256(problem)}
            output.write(json.dumps(item, ensure_ascii=False, sort_keys=True) + '\n')
    del eval_rows
    budget_path = BUDGET_ROOT / 'budget_control.json'
    if not budget_path.is_file():
        raise FileNotFoundError('The existing three-hour budget control is required; refusing to reset it')
    budget = json.loads(budget_path.read_text(encoding='utf-8'))
    remaining = int(float(budget['deadline_unix']) - time.time())
    cap = min(2400, remaining)
    if cap <= 0:
        raise TimeoutError('Three-hour run budget has expired')
    sampling_worker_status = {'state': 'CPU_METADATA_SCAN_QUEUED', 'worker_sha256': WORKER_SHA256,
        'eval_fixture_sha256': EVAL_FIXTURES_SHA256, 'eval_fixture_count': EXPECTED_EVAL_FIXTURES,
        'protected_question_hash_file_sha256': hashlib.sha256(eval_hash_path.read_bytes()).hexdigest(),
        'scope': 'pinned candidate_chat / train rows only', 'target_cases': 4000,
        'deadline_unix': budget['deadline_unix'], 'worker_time_cap_seconds': cap,
        'gpu_used': False, 'model_loaded': False, 'training_started': False,
        'drive_mutated': False, 'eval_payload_used_for_training': False}
    _save_status(sampling_worker_status)
    def _run():
        try:
            sampling_worker_status['state'] = 'CPU_METADATA_SCAN_RUNNING'
            _save_status(sampling_worker_status)
            def progress(update):
                sampling_worker_status['progress'] = update
                _save_status(sampling_worker_status)
            result = module.scan_and_sample(independentDriveAPI, inventory, eval_hash_path,
                SAMPLING_ROOT / 'run', target_cases=4000, seed=20261023, time_limit_s=cap,
                progress_callback=progress,
                preexisting_cache_dirs=(pathlib.Path('/content/mathvisionkid_full_text_training/payload_cache'),))
            sampling_worker_status.update(state='CPU_METADATA_SCAN_COMPLETE',
                result_path=str(SAMPLING_ROOT / 'run' / 'training_view_manifest.json'),
                result_sha256=hashlib.sha256((SAMPLING_ROOT / 'run' / 'training_view_manifest.json').read_bytes()).hexdigest(),
                cases_selected=result['selected_cases'], chat_rows_selected=result['selected_chat_rows'],
                elapsed_seconds=result['elapsed_seconds'])
        except BaseException as error:
            sampling_worker_status.update(state='CPU_METADATA_SCAN_FAILED', error_type=type(error).__name__,
                error=str(error), traceback=traceback.format_exc())
        finally:
            sampling_worker_status['finished_unix'] = time.time()
            _save_status(sampling_worker_status)
    sampling_worker_thread = threading.Thread(target=_run, name='MathVisionKidT4SamplerCPU', daemon=True)
    sampling_worker_thread.start()
    return dict(sampling_worker_status)

print(json.dumps({'state': 'LAUNCHER_READY_CALL_launch_t4_sampler_EXPLICITLY',
    'worker_sha256': WORKER_SHA256, 'eval_fixture_sha256': EVAL_FIXTURES_SHA256,
    'eval_fixture_count': EXPECTED_EVAL_FIXTURES, 'does_not_execute_training': True}, ensure_ascii=False))
